fn every_word(s:&mut Fem2dSnapshot,word:u64){let v=f64::from_bits(word);s.analysis.deformation_scale=v;for n in &mut s.nodes{n.x=v;n.y=v;}for r in &mut s.regions{r.thickness=v;r.mesh_size=v;for p in &mut r.outline{*p=[v,v];}for h in &mut r.holes{for p in h{*p=[v,v];}}}for m in &mut s.materials{m.e=v;m.nu=v;m.rho=v;}for x in &mut s.sections{x.area=v;x.iy=v;}for c in &mut s.load_cases{for x in &mut c.loads{match x{FemLoad::Nodal{value,..}=>*value=v,FemLoad::MemberUdl{wx,wy,..}=>{*wx=v;*wy=v;},FemLoad::Area{pressure,..}=>*pressure=v}}}for c in &mut s.combinations{for x in &mut c.terms{x.factor=v;}}}
