#[cfg(feature="component-app-assembly")]
mod public_populated_owner {
    use super::*;
    use semio_framework_plugin::__semio_dispatch_PluginApp;
    use semio_framework_plugin::plugin_app_close_prelude::*;
    semio_framework_dispatch_macros::dyn_enum_close! {
        /// 🏗️ Actual two FEM2d editor and viewer wrappers close this owning declaration.
        pub(crate) enum FemArtifactApps: PluginApp {
            FemEditor(VcsArtifactApp<EditorApp<crate::editor::fem2d::Fem2dPlayApp>>),
            FemViewer(VcsArtifactApp<ViewerApp<crate::viewer::fem2d::Fem2dViewer>>),
        }
    }
    struct Owned(Option<Fem2dSnapshot>);
    impl Owned { fn new(value:Fem2dSnapshot)->Self{Self(Some(value))} fn get(&self)->&Fem2dSnapshot{self.0.as_ref().unwrap()} }
    impl Drop for Owned { fn drop(&mut self){if let Some(value)=self.0.take(){<Fem2dSnapshot as store::ArtifactSqliteSnapshot>::retire_sqlite_snapshot(value);}} }
    fn exact(a:&Fem2dSnapshot,b:&Fem2dSnapshot){
        use semio_framework_value::{DslValue,Number,ToValue};
        fn same(a:&DslValue,b:&DslValue){match(a,b){
            (DslValue::Number(Number::Float(a)),DslValue::Number(Number::Float(b)))=>assert_eq!(a.to_bits(),b.to_bits()),
            (DslValue::Array(a),DslValue::Array(b))=>{assert_eq!(a.len(),b.len());for(a,b)in a.iter().zip(b){same(a,b);}},
            (DslValue::Object(a),DslValue::Object(b))=>{assert_eq!(a.len(),b.len());for((ka,a),(kb,b))in a.iter().zip(b){assert_eq!(ka,kb);same(a,b);}},
            _=>assert_eq!(a,b),
        }}
        same(&a.to_value(),&b.to_value());
    }
    fn register(){let _plugin=semio_framework_plugin::Plugin::<FemArtifactApps>::builder("fem2d-sqlite-owner").label("FEM2d SQLite owner").version("0.1.0").package_id("semio:fem2d-sqlite-owner").declare_artifact(crate::artifact::<FemArtifactApps>()).try_build().unwrap();}
    #[semio_framework_async_macros::async_test]
    async fn sqlite_snapshot_fem2d_populated_actual_app_public_binary_text_exact_owner(){
        use store::io::{ArtifactDialect,io_mechanism::{io_export_sqlite_snapshot,io_import_sqlite_snapshot,io_route}};
        use store::io_schema::{IoFidelity,SQLITE_SNAPSHOT};
        register();let dialect=ArtifactDialect{artifact_kind:"s.fem.fem2d".into(),standard:"1".into(),subset:"*".into()};let sqlite=ArtifactDialect::from(SQLITE_SNAPSHOT);
        for route in[io_route(&dialect,&sqlite,1).await.unwrap().value,io_route(&sqlite,&dialect,1).await.unwrap().value]{assert_eq!(route.hops.len(),1);assert_eq!(route.fidelity,IoFidelity::Exact);}
        for word in fixture()["ieee754Words"].as_array().unwrap(){let mut value=state();every_word(&mut value,u64::from_str_radix(word.as_str().unwrap(),16).unwrap());let expected=Owned::new(value);
            for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let bytes=io_export_sqlite_snapshot(&dialect,expected.get(),encoding,SqliteDatabaseLimits::default(),&mut |_|true).await.unwrap().value;let actual=Owned::new(io_import_sqlite_snapshot::<Fem2dSnapshot>(&dialect,&bytes,SqliteDatabaseLimits::default(),&mut |_|true).await.unwrap().value);exact(actual.get(),expected.get());assert_eq!(store::ArtifactPack::encode_pack(actual.get()),store::ArtifactPack::encode_pack(expected.get()));assert_eq!(store::ArtifactDsl::print_dsl(actual.get()),store::ArtifactDsl::print_dsl(expected.get()));}
        }
        eprintln!("[DEBUG] FEM2d actual populated app public SQLite both native forms complete exact owner");
    }
    #[semio_framework_async_macros::async_test]
    async fn sqlite_snapshot_fem2d_populated_public_independent_raw_sql_edit_and_retirement(){
        use store::io::{ArtifactDialect,io_mechanism::{io_export_sqlite_snapshot,io_import_sqlite_snapshot}};use std::{io::Write,process::{Command,Stdio}};
        register();let dialect=ArtifactDialect{artifact_kind:"s.fem.fem2d".into(),standard:"1".into(),subset:"*".into()};let expected=Owned::new(state());
        for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let bytes=io_export_sqlite_snapshot(&dialect,expected.get(),encoding,SqliteDatabaseLimits::default(),&mut |_|true).await.unwrap().value;
            let script=r#"import{Database}from'bun:sqlite';const f=JSON.parse(process.argv[1]);const d=Database.deserialize(await Bun.stdin.bytes(),{safeIntegers:true});if(d.query('PRAGMA integrity_check').get().integrity_check!=='ok'||d.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');if(d.query('SELECT COUNT(*) AS n FROM sqlite_schema WHERE type=\'table\'').get().n!==19n)throw Error('all18domainTablesPlusMetadata');for(const[name,count]of Object.entries(f.tableRowCounts)){if(d.query('SELECT COUNT(*) AS n FROM '+name).get().n!==BigInt(count))throw Error('literalRows:'+name);}if(d.query('SELECT authored_id FROM fem2d_node WHERE id=1').get().authored_id!=='')throw Error('literalId');const m=d.query('SELECT artifact_kind,standard,subset,native_encoding FROM semio_snapshot').get();if(m.artifact_kind!=='s.fem.fem2d'||m.standard!=='1'||m.subset!=='*'||m.native_encoding!==process.argv[2])throw Error('publicMetadata');d.query('UPDATE fem2d_material SET name=? WHERE id=1').run('independent 日本\u0000');await Bun.write(Bun.stdout,d.serialize());d.close();"#;
            let mut child=Command::new("bun").args(["--eval",script,&fixture().to_string(),encoding.as_str()]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let edited=child.wait_with_output().unwrap();assert!(edited.status.success(),"{}",String::from_utf8_lossy(&edited.stderr));let actual=Owned::new(io_import_sqlite_snapshot::<Fem2dSnapshot>(&dialect,&edited.stdout,SqliteDatabaseLimits::default(),&mut |_|true).await.unwrap().value);let mut literal=state();literal.materials[0].name="independent 日本\0".into();let literal=Owned::new(literal);exact(actual.get(),literal.get());assert_eq!(store::ArtifactPack::encode_pack(actual.get()),store::ArtifactPack::encode_pack(literal.get()));assert_eq!(store::ArtifactDsl::print_dsl(actual.get()),store::ArtifactDsl::print_dsl(literal.get()));
        }
        eprintln!("[DEBUG] FEM2d public independent raw SQL edit restored complete literal owner and explicit retirement");
    }
