    }
    for tool_id in ENERGY_MODEL_RETAINED_TOOL_IDS {
        let command = <EnergyModelEditor as ArtifactEditor>::command_from_action(tool_id, None).unwrap_or_else(|error| panic!("action {tool_id} has no command: {error:?}"));
